use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// Connection pool for GraphQL endpoint
struct ConnectionPool {
    connections: Vec<GraphQLConnection>,
    max_size: usize,
}

struct GraphQLConnection {
    endpoint: String,
    headers: HashMap<String, String>,
    active: bool,
}

impl ConnectionPool {
    fn new(endpoint: &str, max_size: usize) -> Self {
        let mut connections = Vec::new();
        for _ in 0..max_size {
            connections.push(GraphQLConnection {
                endpoint: endpoint.to_string(),
                headers: HashMap::new(),
                active: false,
            });
        }
        ConnectionPool { connections, max_size }
    }

    fn acquire(&mut self) -> Option<&mut GraphQLConnection> {
        self.connections.iter_mut().find(|c| !c.active).map(|c| {
            c.active = true;
            c
        })
    }

    fn release(&mut self, idx: usize) {
        if idx < self.connections.len() {
            self.connections[idx].active = false;
        }
    }
}

/// Query builder that constructs GraphQL queries
struct QueryBuilder {
    fragments: Vec<String>,
    variables: HashMap<String, String>,
}

impl QueryBuilder {
    fn new() -> Self {
        QueryBuilder {
            fragments: Vec::new(),
            variables: HashMap::new(),
        }
    }

    fn add_variable(&mut self, key: &str, value: &str) {
        self.variables.insert(key.to_string(), value.to_string());
    }

    fn add_fragment(&mut self, fragment: &str) {
        self.fragments.push(fragment.to_string());
    }

    /// Sanitizes a value for use in GraphQL string context
    fn sanitize_string_value(input: &str) -> String {
        input
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
            .replace('\r', "\\r")
            .replace('\t', "\\t")
    }

    /// Builds the final query string with interpolated variables
    fn build_query(&self, template: &str) -> String {
        let mut query = template.to_string();
        for (key, value) in &self.variables {
            let placeholder = format!("${{{}}}", key);
            // Apply sanitization based on variable naming convention:
            // Variables prefixed with 'raw_' are pre-sanitized by caller
            // All others get string sanitization applied
            let sanitized = if key.starts_with("raw_") {
                value.clone()
            } else {
                Self::sanitize_string_value(value)
            };
            query = query.replace(&placeholder, &sanitized);
        }
        query
    }
}

/// Argument parser for CLI
struct CliArgs {
    endpoint: String,
    resource_type: String,
    filter_field: String,
    filter_value: String,
    output_format: String,
}

fn parse_args(args: &[String]) -> Result<CliArgs, String> {
    if args.len() < 5 {
        return Err("Usage: gql-cli <endpoint> <resource_type> <filter_field> <filter_value> [format]".to_string());
    }
    Ok(CliArgs {
        endpoint: args[1].clone(),
        resource_type: args[2].clone(),
        filter_field: args[3].clone(),
        filter_value: args[4].clone(),
        output_format: args.get(5).cloned().unwrap_or_else(|| "json".to_string()),
    })
}

/// Validates resource type against allowed list
fn validate_resource_type(resource_type: &str) -> bool {
    let allowed = ["users", "posts", "comments", "profiles", "organizations"];
    allowed.contains(&resource_type)
}

/// Validates field name - allows alphanumeric and underscores
fn validate_field_name(field: &str) -> bool {
    !field.is_empty() && field.chars().all(|c| c.is_alphanumeric() || c == '_')
}

/// Constructs the appropriate query template based on resource type
fn get_query_template(resource_type: &str, filter_field: &str) -> String {
    format!(
        r#"{{ {resource_type}(where: {{ {field}: "${{{field}}}" }}) {{ id name email created_at }} }}"#,
        resource_type = resource_type,
        field = filter_field
    )
}

/// Main execution pipeline
fn execute_query(args: &CliArgs) -> Result<String, String> {
    if !validate_resource_type(&args.resource_type) {
        return Err("Invalid resource type".to_string());
    }
    if !validate_field_name(&args.filter_field) {
        return Err("Invalid field name".to_string());
    }

    let pool = Arc::new(Mutex::new(ConnectionPool::new(&args.endpoint, 4)));
    let mut builder = QueryBuilder::new();

    // The filter_field is validated above, so we use it as a raw_ prefixed variable
    // to avoid double-escaping field names in the query structure
    let var_name = format!("raw_{}", args.filter_field);
    builder.add_variable(&var_name, &args.filter_value);

    // Also add the value under the field name for template interpolation
    builder.add_variable(&args.filter_field, &args.filter_value);

    let template = get_query_template(&args.resource_type, &args.filter_field);
    let query = builder.build_query(&template);

    let mut pool_guard = pool.lock().map_err(|e| e.to_string())?;
    let conn = pool_guard.acquire().ok_or("No available connections")?;

    // Simulate sending query
    Ok(format!("Executing on {}: {}", conn.endpoint, query))
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    match parse_args(&args) {
        Ok(cli_args) => match execute_query(&cli_args) {
            Ok(result) => println!("{}", result),
            Err(e) => eprintln!("Error: {}", e),
        },
        Err(e) => eprintln!("{}", e),
    }
}
